export function createScheduler(options = {}) {
  const { maxSize = Infinity } = options

  if (maxSize !== Infinity && (typeof maxSize !== 'number' || !Number.isInteger(maxSize) || maxSize < 1)) {
    throw new RangeError('maxSize must be a positive integer or Infinity')
  }

  // In-memory FIFO queue. This deployment cannot supply the storage dependency
  // a durable outbox would need, so persistence stays out of scope.
  const tasks = []

  return {
    mode: 'memory',

    get size() {
      return tasks.length
    },

    async enqueue(task) {
      if (task === null || typeof task !== 'object') {
        throw new TypeError('task must be an object')
      }
      if (tasks.length >= maxSize) {
        throw new Error(\`queue is full (maxSize \${maxSize})\`)
      }
      tasks.push(task)
      return { queued: true, size: tasks.length }
    },

    async drain() {
      return tasks.splice(0, tasks.length)
    },

    async peek() {
      return tasks.length > 0 ? tasks[0] : undefined
    },
  }
}

export function createScheduler(options = {}) {
  const { maxQueueSize = Infinity } = options
  if (typeof maxQueueSize !== 'number' || Number.isNaN(maxQueueSize) || maxQueueSize <= 0) {
    throw new TypeError('maxQueueSize must be a positive number')
  }

  let tasks = []

  return {
    mode: 'memory',

    get size() {
      return tasks.length
    },

    async enqueue(task) {
      if (task === undefined) {
        throw new TypeError('task must not be undefined')
      }
      if (tasks.length >= maxQueueSize) {
        throw new Error(`queue is full (maxQueueSize=${maxQueueSize})`)
      }
      tasks.push(task)
      return { queued: true, size: tasks.length }
    },

    async drain() {
      const drained = tasks
      tasks = []
      return drained
    },
  }
}

export function watchChanges({ fs, dir, onEvent, intervalMs = 100 }) {
  let known = null
  let closed = false
  let timer = null

  const snapshot = () => {
    let entries
    try {
      entries = fs.readdir(dir, { withFileTypes: true })
    } catch {
      return []
    }
    return Array.from(entries ?? []).map(entry =>
      typeof entry === 'string' ? entry : entry.name,
    )
  }

  const poll = () => {
    if (closed) return
    const current = snapshot()
    if (known !== null) {
      for (const name of current) {
        if (!known.includes(name)) onEvent(name)
      }
      for (const name of known) {
        if (!current.includes(name)) onEvent(name)
      }
    }
    known = current
    timer = setTimeout(poll, intervalMs)
    timer?.unref?.()
  }

  // Seed the baseline synchronously so the first poll compares against it.
  known = snapshot()
  timer = setTimeout(poll, intervalMs)
  timer?.unref?.()

  return {
    close() {
      closed = true
      if (timer) clearTimeout(timer)
      timer = null
    },
  }
}
